import { ok, fail } from './result.js';
import { getCustomer, normalizeId, TIER_DISCOUNTS } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { isValidDate, calculateDueDate } from './dates.js';
import { lineTotal, lineDiscount, lineVAT, invoiceTotals } from './totals.js';

// Re-export totals functions for backward compatibility
export { lineTotal, lineDiscount, lineVAT, invoiceTotals };

/**
 * Create an invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer exists
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) {
    return customerResult;
  }

  const customer = customerResult.value;

  // Validate issue date format and validity
  if (!isValidDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  // Validate terms
  const validTerms = ['NET14', 'NET30', 'EOM'];
  if (!validTerms.includes(terms)) {
    return fail('TERMS_INVALID');
  }

  // Calculate due date
  const dueDate = calculateDueDate(issueDate, terms);

  // Validate lines is not empty
  if (!lines || lines.length === 0) {
    return fail('NO_LINES');
  }

  // Build and validate invoice lines
  const invoiceLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Determine discount: explicit discountPercent wins, otherwise use tier discount
    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : TIER_DISCOUNTS[customer.tier];

    // Validate discountPercent
    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
      return fail('DISCOUNT_INVALID');
    }

    // Look up product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) {
      return productResult;
    }

    const product = productResult.value;
    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
    terms,
    dueDate,
  });
}


/**
 * Add or update a line on an invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check status is draft
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  // Validate discountPercent
  const discount = discountPercent ?? 0;
  if (typeof discount !== 'number' || discount < 0 || discount > 100) {
    return fail('DISCOUNT_INVALID');
  }

  // Look up product
  const productResult = getProduct(sku);
  if (!productResult.ok) {
    return productResult;
  }

  const product = productResult.value;

  // Create new lines array
  const newLines = invoice.lines.map((line) => ({ ...line }));

  // Check if SKU already exists
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex !== -1) {
    // Update existing line's qty
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    // Add new line
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: discount,
    });
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }}
 * @param {string} sku
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check status is draft
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Find the line to remove
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);

  if (lineIndex === -1) {
    return fail('LINE_NOT_FOUND');
  }

  // Check if this is the last line
  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  // Create new lines array without the removed line
  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Apply a voucher to a draft invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array, voucher?: { code: string, amount: number } }} invoice
 * @param {{ code: string, amount: number }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, voucher: { code: string, amount: number } } } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, { code, amount }) {
  // Check status is draft
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Check if voucher already exists
  if (invoice.voucher) {
    return fail('VOUCHER_EXISTS');
  }

  // Validate amount is a positive integer
  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: invoice.lines.map((line) => ({ ...line })),
    ...(invoice.terms && { terms: invoice.terms }),
    ...(invoice.dueDate && { dueDate: invoice.dueDate }),
    voucher: { code, amount },
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array, terms?: string, dueDate?: string, voucher?: { code: string, amount: number } }} invoice
 * @param {Array<string>} existingNumbers - Invoice numbers already issued
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, number: string, lines: Array, terms?: string, dueDate?: string, voucher?: { code: string, amount: number } } } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check status is draft
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Generate next invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'issued',
    number,
    lines: invoice.lines.map((line) => ({ ...line })),
    ...(invoice.terms && { terms: invoice.terms }),
    ...(invoice.dueDate && { dueDate: invoice.dueDate }),
    ...(invoice.voucher && { voucher: { ...invoice.voucher } }),
  });
}

