  };

  const totals = invoiceTotals(invoice);
  // subtotal: 85000
  // line discount: 0
  // bulk discount: 2125
  // total discount: 0 + 2125 = 2125
  // amount after discount: 82875
  // vat: 82875 * 0.21 = 17403.75 ≈ 17404
  // total: 85000 - 2125 + 17404 = 100279
  assert.equal(totals.subtotal, 85000);
