    ],
  };

  const totals = invoiceTotals(invoice);
  // subtotal: 85000 + 47500 = 132500
  // discount from line 1: 0, bulk: 2125
  // discount from line 2: 0, bulk: 0
  // total discount: 2125
  // vat line 1: (85000 - 2125) * 0.21 = 17403.75 ≈ 17404
  // vat line 2: 47500 * 0.21 = 9975
  // total vat: 17404 + 9975 = 27379
  // total: 132500 - 2125 + 27379 = 157754
  assert.equal(totals.subtotal, 132500);
  assert.equal(totals.discount, 2125);
  assert.equal(totals.vat, 27379);
  assert.equal(totals.total, 157754);
});

test('invoiceTotals with high line discount and bulk discount stacking', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 50, vatRate: 21 }],
  };

  const totals = invoiceTotals(invoice);
  // subtotal: 85000
  // line discount: 42500 (50%)
  // remaining: 42500
  // bulk discount: 1062 (2.5% of 42500, banker's rounding)
  // total discount: 42500 + 1062 = 43562
  // amount after discounts: 41438
  // vat: 41438 * 0.21 = 8701.98 ≈ 8702 (banker's rounding)
  // total: 85000 - 43562 + 8702 = 50140
  assert.equal(totals.subtotal, 85000);
