// invoiceTotals with bulk discount tests
test('invoiceTotals with single line qty 10 applies bulk discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 0, vatRate: 21 }],
  };

  const totals = invoiceTotals(invoice);
  // subtotal: 85000
  // line discount: 0
  // bulk discount: 2125
  // total discount: 0 + 2125 = 2125
  // amount after discount: 82875
  // vat: 82875 * 0.21 = 17403.75 ≈ 17404
  // total: 85000 - 2125 + 17404 = 100279
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 2125);
  assert.equal(totals.vat, 17404);
  assert.equal(totals.total, 100279);
});

test('invoiceTotals with qty 9 no bulk discount', () => {
  const invoice = {
    lines: [{ qty: 9, unitPrice: 8500, discountPercent: 0, vatRate: 21 }],
  };

  const totals = invoiceTotals(invoice);
  // subtotal: 76500
  // line discount: 0
  // bulk discount: 0 (qty < 10)
