import test from 'node:test';
import assert from 'node:assert/strict';
import { lineTotal, lineDiscount, lineVAT, bulkDiscount, invoiceTotals } from '../src/totals.js';

// lineTotal tests
test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 10, unitPrice: 8500 }), 85000);
});

test('lineTotal with qty 1', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 9500 }), 9500);
});

test('lineTotal with large quantities', () => {
  assert.equal(lineTotal({ qty: 100, unitPrice: 1500 }), 150000);
});

test('lineTotal applies rounding for fractional results', () => {
  // 3 * 1.5 = 4.5 cents, rounds to 4 (banker's rounding, half to even)
  assert.equal(lineTotal({ qty: 3, unitPrice: 1.5 }), 4);
});

// lineDiscount tests
test('lineDiscount calculates discount as lineTotal * discountPercent / 100', () => {
  // 10 * 8500 = 85000, 10% discount = 8500
  assert.equal(lineDiscount({ qty: 10, unitPrice: 8500, discountPercent: 10 }), 8500);
});

test('lineDiscount with 0% discount', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 8500, discountPercent: 0 }), 0);
});

test('lineDiscount with 100% discount', () => {
  // 10 * 8500 = 85000, 100% discount = 85000
  assert.equal(lineDiscount({ qty: 10, unitPrice: 8500, discountPercent: 100 }), 85000);
});

test('lineDiscount defaults to 0% if discountPercent is missing', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 8500 }), 0);
});

test('lineDiscount with decimal discountPercent', () => {
  // 10 * 8500 = 85000, 12.5% discount = 10625
  assert.equal(lineDiscount({ qty: 10, unitPrice: 8500, discountPercent: 12.5 }), 10625);
});

test('lineDiscount clamps to 0 if result is negative (should not happen but safety)', () => {
  // Negative discount should be clamped to 0
  const discount = lineDiscount({ qty: 1, unitPrice: 100, discountPercent: 0 });
  assert.equal(discount, 0);
});

// lineVAT tests
test('lineVAT calculates VAT on amount after discount', () => {
  // 9 * 8500 = 76500, no discount, 21% VAT = 16065
  assert.equal(lineVAT({ qty: 9, unitPrice: 8500, discountPercent: 0, vatRate: 21 }), 16065);
});

test('lineVAT with discount reduces VAT base', () => {
  // 9 * 8500 = 76500, 10% discount = 7650, amount after discount = 68850, 21% VAT = 14458
  assert.equal(lineVAT({ qty: 9, unitPrice: 8500, discountPercent: 10, vatRate: 21 }), 14458);
});

test('lineVAT with 0% VAT rate', () => {
  assert.equal(lineVAT({ qty: 9, unitPrice: 8500, discountPercent: 0, vatRate: 0 }), 0);
});

test('lineVAT with 9% VAT rate', () => {
  // 9 * 37 = 333, no discount, 9% VAT = 30 (333 * 0.09 = 29.97, rounds to 30 with banker's rounding)
  assert.equal(lineVAT({ qty: 9, unitPrice: 37, discountPercent: 0, vatRate: 9 }), 30);
});

test('lineVAT defaults vatRate to 0 if missing', () => {
  assert.equal(lineVAT({ qty: 10, unitPrice: 8500, discountPercent: 0 }), 0);
});

test('lineVAT clamps to 0 if result is negative (should not happen)', () => {
  const vat = lineVAT({ qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 0 });
  assert.equal(vat, 0);
});

// bulkDiscount tests
test('bulkDiscount with qty < 10 returns 0', () => {
  assert.equal(bulkDiscount({ qty: 1, unitPrice: 8500, discountPercent: 0 }), 0);
  assert.equal(bulkDiscount({ qty: 5, unitPrice: 8500, discountPercent: 0 }), 0);
  assert.equal(bulkDiscount({ qty: 9, unitPrice: 8500, discountPercent: 0 }), 0);
});

test('bulkDiscount with qty >= 10 applies 2.5% to amount after line discount', () => {
  // 10 * 8500 = 85000, no line discount, 2.5% bulk discount = 2125
  assert.equal(bulkDiscount({ qty: 10, unitPrice: 8500, discountPercent: 0 }), 2125);
});

test('bulkDiscount with qty 11', () => {
  // 11 * 8500 = 93500, no line discount, 2.5% bulk discount = 2337.5 ≈ 2338
  assert.equal(bulkDiscount({ qty: 11, unitPrice: 8500, discountPercent: 0 }), 2338);
});

test('bulkDiscount applied after line discount', () => {
  // 10 * 8500 = 85000, line discount 10% = 8500, remaining = 76500, bulk discount 2.5% = 1912.5 ≈ 1912
  assert.equal(bulkDiscount({ qty: 10, unitPrice: 8500, discountPercent: 10 }), 1912);
});

test('bulkDiscount with high line discount', () => {
  // 10 * 8500 = 85000, line discount 50% = 42500, remaining = 42500, bulk discount 2.5% = 1062.5 ≈ 1062
  assert.equal(bulkDiscount({ qty: 10, unitPrice: 8500, discountPercent: 50 }), 1062);
});

test('bulkDiscount with 100% line discount', () => {
  // 10 * 8500 = 85000, line discount 100% = 85000, remaining = 0, bulk discount 2.5% = 0
  assert.equal(bulkDiscount({ qty: 10, unitPrice: 8500, discountPercent: 100 }), 0);
});

test('bulkDiscount defaults discountPercent to 0 if missing', () => {
  // 10 * 8500 = 85000, no line discount, 2.5% bulk discount = 2125
  assert.equal(bulkDiscount({ qty: 10, unitPrice: 8500 }), 2125);
});

test('bulkDiscount with large quantity', () => {
  // 100 * 8500 = 850000, no line discount, 2.5% bulk discount = 21250
  assert.equal(bulkDiscount({ qty: 100, unitPrice: 8500, discountPercent: 0 }), 21250);
});

test('bulkDiscount exactly at threshold (qty 10)', () => {
  // 10 * 100 = 1000, no line discount, 2.5% bulk discount = 25
  assert.equal(bulkDiscount({ qty: 10, unitPrice: 100, discountPercent: 0 }), 25);
});

test('bulkDiscount just below threshold (qty 9)', () => {
  // 9 * 100 = 900, no line discount, but qty < 10 so no bulk discount
  assert.equal(bulkDiscount({ qty: 9, unitPrice: 100, discountPercent: 0 }), 0);
});

test('lineVAT calculated on amount after both line and bulk discounts', () => {
  // 10 * 8500 = 85000
  // line discount 10% = 8500, remaining = 76500
  // bulk discount 2.5% = 1912, remaining = 74588
  // VAT 21% = 74588 * 0.21 = 15663.48 ≈ 15663
  assert.equal(lineVAT({ qty: 10, unitPrice: 8500, discountPercent: 10, vatRate: 21 }), 15663);
});

test('lineVAT with only bulk discount (no line discount)', () => {
  // 10 * 8500 = 85000
  // no line discount
  // bulk discount 2.5% = 2125, remaining = 82875
  // VAT 21% = 82875 * 0.21 = 17403.75 ≈ 17404
  assert.equal(lineVAT({ qty: 10, unitPrice: 8500, discountPercent: 0, vatRate: 21 }), 17404);
});

test('lineVAT with qty < 10 ignores bulk discount', () => {
  // 9 * 8500 = 76500
  // no line discount
  // no bulk discount (qty < 10)
  // VAT 21% = 76500 * 0.21 = 16065
  assert.equal(lineVAT({ qty: 9, unitPrice: 8500, discountPercent: 0, vatRate: 21 }), 16065);
});

// invoiceTotals tests
test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 8500 }],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.total, 42500);
});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 9, unitPrice: 8500 }, // 76500
      { qty: 5, unitPrice: 9500 }, // 47500
      { qty: 1, unitPrice: 120000 }, // 120000
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 244000);
  assert.equal(totals.total, 244000);
});

test('invoiceTotals with mixed VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 8500 }, // 21% VAT product: 8500
      { qty: 9, unitPrice: 37 }, // 9% VAT product: 333
      { qty: 1, unitPrice: 60000 }, // 0% VAT product: 60000
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 68833);
  assert.equal(totals.total, 68833);
});

test('invoiceTotals returns a new object', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 1000 }],
  };

  const totals1 = invoiceTotals(invoice);
  const totals2 = invoiceTotals(invoice);

  assert.notEqual(totals1, totals2);
  assert.deepEqual(totals1, totals2);
});

test('invoiceTotals with single line and discount', () => {
  const invoice = {
    lines: [{ qty: 9, unitPrice: 8500, discountPercent: 10 }],
  };

  const totals = invoiceTotals(invoice);
  // subtotal: 76500, discount: 7650, total: 68850
  assert.equal(totals.subtotal, 76500);
  assert.equal(totals.discount, 7650);
  assert.equal(totals.total, 68850);
});

test('invoiceTotals with multiple lines and discounts', () => {
  const invoice = {
    lines: [
      { qty: 9, unitPrice: 8500, discountPercent: 10 }, // 76500 - 7650 = 68850
      { qty: 5, unitPrice: 9500, discountPercent: 20 },  // 47500 - 9500 = 38000
    ],
  };

  const totals = invoiceTotals(invoice);
  // subtotal: 76500 + 47500 = 124000
  // discount: 7650 + 9500 = 17150
  // total: 124000 - 17150 = 106850
  assert.equal(totals.subtotal, 124000);
  assert.equal(totals.discount, 17150);
  assert.equal(totals.total, 106850);
});

test('invoiceTotals with mixed discount and no discount lines', () => {
  const invoice = {
    lines: [
      { qty: 9, unitPrice: 8500, discountPercent: 10 }, // discount: 8500, no bulk (qty < 10)
      { qty: 5, unitPrice: 9500, discountPercent: 0 },   // discount: 0, no bulk
    ],
  };

  const totals = invoiceTotals(invoice);
  // line 1: subtotal: 76500, discount: 8500, no bulk
  // line 2: subtotal: 47500, discount: 0, no bulk
  // subtotal: 76500 + 47500 = 124000
  // discount: 8500 + 0 = 8500
  // total: 124000 - 8500 = 115500
  assert.equal(totals.subtotal, 124000);
  assert.equal(totals.discount, 8500);
  assert.equal(totals.total, 115500);
});

test('invoiceTotals clamps total to 0 if discount equals subtotal', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 100 }],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 85000);
  assert.equal(totals.total, 0);
});

test('invoiceTotals includes VAT field', () => {
  const invoice = {
    lines: [{ qty: 9, unitPrice: 8500, discountPercent: 0, vatRate: 21 }],
