    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 0, vatRate: 21 }],
  };

  const totals = invoiceTotals(invoice);
  // subtotal: 85000
  // line discount: 0
  // bulk discount: 2125
  // total discount: 0 + 2125 = 2125
  // amount after discount: 82875
