  const totals = invoiceTotals(invoice);
  // subtotal: 76500
  // line discount: 0
  // bulk discount: 0 (qty < 10)
  // total discount: 0
  // vat: 76500 * 0.21 = 16065
  // total: 76500 + 16065 = 92565
  assert.equal(totals.subtotal, 76500);
