    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 10, vatRate: 21 }],
  };

  const totals = invoiceTotals(invoice);
  // subtotal: 85000
  // line discount: 8500 (10%)
  // remaining after line discount: 76500
  // bulk discount: 1912 (2.5% of 76500)
  // total discount: 8500 + 1912 = 10412
  // amount after discounts: 74588
  // vat: 74588 * 0.21 = 15663.48 ≈ 15663
  // total: 85000 - 10412 + 15663 = 90251
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 10412);
  assert.equal(totals.vat, 15663);
  assert.equal(totals.total, 90251);
});

test('invoiceTotals with multiple lines some with bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, discountPercent: 0, vatRate: 21 }, // subtotal: 85000, bulk discount: 2125
      { qty: 5, unitPrice: 9500, discountPercent: 0, vatRate: 21 },  // subtotal: 47500, bulk discount: 0
    ],
  };

  const totals = invoiceTotals(invoice);
  // subtotal: 85000 + 47500 = 132500
  // discount from line 1: 0, bulk: 2125
  // discount from line 2: 0, bulk: 0
  // total discount: 2125
  // vat line 1: (85000 - 2125) * 0.21 = 17403.75 ≈ 17404
  // vat line 2: 47500 * 0.21 = 9975
  // total vat: 17404 + 9975 = 27379
  // total: 132500 - 2125 + 27379 = 157754
  assert.equal(totals.subtotal, 132500);
  assert.equal(totals.discount, 2125);
  assert.equal(totals.vat, 27379);
  assert.equal(totals.total, 157754);
});

test('invoiceTotals with high line discount and bulk discount stacking', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 50, vatRate: 21 }],
  };

  const totals = invoiceTotals(invoice);
  // subtotal: 85000
  // line discount: 42500 (50%)
  // remaining: 42500
  // bulk discount: 1062 (2.5% of 42500, banker's rounding)
  // total discount: 42500 + 1062 = 43562
  // amount after discounts: 41438
  // vat: 41438 * 0.21 = 8701.98 ≈ 8702 (banker's rounding)
  // total: 85000 - 43562 + 8702 = 50140
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 43562);
  assert.equal(totals.vat, 8702);
  assert.equal(totals.total, 50140);
});

test('invoiceTotals with qty 10 and 0% VAT line', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 0, vatRate: 0 }],
  };

  const totals = invoiceTotals(invoice);
  // subtotal: 85000
  // discount: 2125
  // vat: 0
  // total: 85000 - 2125 = 82875
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 2125);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 82875);
});

test('invoiceTotals with large quantity bulk discount', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 8500, discountPercent: 0, vatRate: 21 }],
  };

  const totals = invoiceTotals(invoice);
  // subtotal: 850000
  // bulk discount: 21250 (2.5% of 850000)
  // vat: (850000 - 21250) * 0.21 = 828750 * 0.21 = 174037.5 ≈ 174038 (banker's rounding)
  // total: 850000 - 21250 + 174038 = 1002788
  assert.equal(totals.subtotal, 850000);
  assert.equal(totals.discount, 21250);
  assert.equal(totals.vat, 174038);
  assert.equal(totals.total, 1002788);
});

